const output = $input.first().json.output;

// AI повертає JSON як текст
const parsed = JSON.parse(output);

return [
  {
    json: {
      platform: "instagram",
      post: parsed.instagram_post,
      hashtags: parsed.instagram_hashtags,
      image_prompt: parsed.instagram_image_prompt
    }
  },
  {
    json: {
      platform: "telegram",
      post: parsed.telegram_post,
      hashtags: parsed.telegram_hashtags,
      image_prompt: parsed.telegram_image_prompt
    }
  }
];
